'use strict';const cases=[['set5_046','rope'],['set5_047','mask'],['set5_047','territory']];function setup(c,s,id,variant){s.phase='MAIN_PHASE';s.turnNumber=3;s.activePlayerId=variant==='territory'?'P2':'P1';s.pendingEffect=null;for(const p of s.playerOrder)for(const z of ['field','hand','food','discard','territory'])s.player(p)[z]=[];for(const p of s.playerOrder)s.player(p).availableCost=10;function put(id,z,p='P1'){const d=c.getCardDefinition(id),x=new c.CardInstance({instanceId:s.nextInstanceId(),cardId:id,ownerId:p,controllerId:p,zone:z,baseHp:d.baseHp,currentHp:d.baseHp});s.player(p)[z.toLowerCase()].push(x);return x;}if(variant==='territory'){put('set5_028','FIELD');put('namitentou','FIELD').currentHp=100;put('kabutomushi','FIELD','P2');put(id,'TERRITORY').faceDown=true;}else{put(id,'HAND');if(variant==='rope'){put('kabutomushi','FIELD');put('namitentou','FOOD','P2');put('set6_056','HAND','P2');}else{put('set5_028','FIELD').attackedThisTurn=true;put('set5_064','HAND');}}}module.exports={cases,setup};